export function lookup(db, input) {
  return db.query("SELECT name FROM accounts WHERE id = " + input);
}

export function lookup(db, input) {
  return db.query("SELECT name FROM accounts WHERE id = $1", [input]);
}

CREATE FUNCTION lookup(v text) RETURNS SETOF text AS $$
BEGIN
 RETURN QUERY EXECUTE 'SELECT name FROM accounts WHERE id = ' || v;
END $$ LANGUAGE plpgsql;

CREATE FUNCTION lookup(v text) RETURNS SETOF text AS $$
BEGIN
 RETURN QUERY EXECUTE 'SELECT name FROM accounts WHERE id = $1' USING v;
END $$ LANGUAGE plpgsql;

-- Tenant-isolated reporting uses report_user for every client.
ALTER ROLE report_user BYPASSRLS;
GRANT SELECT ON private_orders TO report_user;

-- PostgreSQL tenant-scoped reporting uses a non-owner restricted role.
ALTER TABLE private_orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE private_orders FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_rows ON private_orders USING (tenant_id = current_user);

-- This job promises read-only counts from a shared production database.
TRUNCATE private_orders CASCADE;
SELECT count(*) FROM private_orders;

-- Public untrusted reporting endpoint forwards arbitrary query text with no client cancellation/result cap.
SET statement_timeout = 0;
SET lock_timeout = 0;
SELECT * FROM large_orders a CROSS JOIN large_orders b;

-- Authorized bounded reporting session; caller also caps result bytes.
SET statement_timeout = 1000;
SET lock_timeout = 200;
SELECT day, total FROM public_daily_totals LIMIT 20;

